<script>
 import { activitySession,activityAvailability,ACTIVITY_TABS } from './activity-state.js';
 import { activityInventoryValid,activityRows,activityProcess,activityProcessName,activityCpu,activityGraph,activityFormatBytes,activityDiagnosticText,ACTIVITY_COUNTERS } from './activity-projections.js';
 import { activityMenuItems } from './activity-menus.js';
 import './activity.css';
 let {state: activityState,profile,windowId,getInventory,getSceneTime,execute,registerView,available=true,active=true}=$props();
 let root,scroller,error=$state(''),saveName=$state('Process Sample.txt');
 let session=$derived(activitySession(activityState,windowId)),capability=$derived(activityAvailability(profile));
 let inventory=$derived(getInventory?.()),time=$derived(getSceneTime?.()??session?.samples.at(-1)?.time??0);
 let rows=$derived(activityRows(inventory,session,activityState.preferences,time)),process=$derived(activityProcess(inventory,session?.selectedId));
 let columns=$derived(session?.tab==='cpu'?['name','cpu','cpuTimeMs','threads','wakeups','pid']:session?.tab==='memory'?['name','memoryBytes','threads','pid']:session?.tab==='energy'?['name','energyImpact','wakeups','pid']:session?.tab==='disk'?['name','bytesWritten','bytesRead','pid']:['name','bytesSent','bytesReceived','pid']);
 const labels={name:'Process Name',cpu:'% CPU',cpuTimeMs:'CPU Time',threads:'Threads',wakeups:'Idle Wake Ups',pid:'PID',memoryBytes:'Memory',energyImpact:'Energy Impact',bytesWritten:'Bytes Written',bytesRead:'Bytes Read',bytesSent:'Sent Bytes',bytesReceived:'Rcvd Bytes'};
 let graph=$derived(activityGraph(session,session?.tab)),maximum=$derived(Math.max(session?.tab==='cpu'?100:1,...graph)),points=$derived(graph.map((v,i)=>`${graph.length>1?i*240/(graph.length-1):0},${56-v*54/maximum}`).join(' '));
 let latest=$derived(session?.samples.at(-1)),diagnostic=$derived(process&&activityInventoryValid(inventory)?activityDiagnosticText(inventory,process,time,session?.mode):'The original process lifecycle has exited or its inventory is unavailable.');
 const bytes=activityFormatBytes;
 function cell(row,key){if(key==='name')return activityProcessName(inventory,row);if(key==='pid')return row.pid;if(key==='cpu')return activityCpu(row,time).toFixed(1);if(key==='cpuTimeMs')return (row.counters.cpuTimeMs/1000).toFixed(2)+' s';if(/Bytes/u.test(key)||key.startsWith('bytes'))return bytes(row.counters[key]);return row.counters[key].toFixed(key==='energyImpact'?1:0);}
 async function send(command,payload={}){const result=await execute?.(command,{windowId},payload);error=result?.status==='rejected'?result.error?.message??'Command unavailable.':'';return result;}
 $effect(()=>{const id=windowId;if(!root||typeof registerView!=='function'||!session)return;const originalRoot=root,originalState=activityState,originalSession=session,originalScroller=scroller,mounted=()=>root===originalRoot&&root.isConnected&&activityState===originalState&&activitySession(activityState,id)===originalSession&&available===true;const facade={available:mounted,focus(controlId,guard){if(guard?.()!==true||!mounted())return false;const node=Array.from(root.querySelectorAll('[data-control]')).find(n=>n.dataset.control===controlId);if(!node||node.disabled)return false;node.focus();return guard()===true&&mounted()&&document.activeElement===node;},scroll({top},guard){if(guard?.()!==true||!mounted()||!originalScroller||scroller!==originalScroller)return false;originalScroller.scrollTop=top;return guard()===true&&mounted()&&Math.abs(originalScroller.scrollTop-Math.min(top,Math.max(0,originalScroller.scrollHeight-originalScroller.clientHeight)))<1;}};const unregister=registerView(id,facade);return ()=>{if(typeof unregister==='function')unregister();};});
</script>
{#if session}
<section bind:this={root} class="activity-app" class:classic={/high-sierra|mojave/u.test(profile.id)} class:windows={capability.windows} class:active aria-label={capability.label}>
 <nav class="activity-menus" aria-label="Application menus">{#each activityMenuItems(activityState,windowId) as menu}<details><summary>{menu.label}</summary><div class="activity-menu-popup">{#each menu.items as item}<button disabled={!item.enabled} onclick={()=>send(item.command,item.payload)}>{item.label}</button>{/each}</div></details>{/each}</nav>
 {#if session.mode==='main'}
 <header class="activity-toolbar"><div class="activity-actions"><button data-control="quit" aria-label={capability.windows?'End task':'Quit process'} title="Quit selected process" disabled={!process} onclick={()=>send('activity.requestQuit',{force:false})}>⊗</button><button data-control="inspect" title="Inspect selected process" aria-label="Inspect selected process" disabled={!process} onclick={()=>send('activity.inspect',{mode:'inspector'})}>ⓘ</button><details><summary aria-label="Process actions">⚙⌄</summary><div class="activity-menu-popup"><button disabled={!process} onclick={()=>send('activity.inspect',{mode:'sample'})}>Sample Process</button><button onclick={()=>send('activity.refresh')}>Update Now</button></div></details></div><div class="activity-tabs" role="tablist" aria-label="Resource">{#each ACTIVITY_TABS as tab}<button role="tab" aria-selected={session.tab===tab} class:selected={session.tab===tab} data-control={'tab-'+tab} onclick={()=>send('activity.tab',{tab})}>{tab==='cpu'?'CPU':tab[0].toUpperCase()+tab.slice(1)}</button>{/each}</div><label class="activity-search"><span aria-hidden="true">⌕</span><input data-control="search" type="search" aria-label="Search processes" placeholder="Search" value={session.query} oninput={e=>send('activity.search',{query:e.currentTarget.value})}/></label></header>
 <div class="activity-body">
 {#if capability.windows}<aside class="activity-windows-navigation"><h2>Task Manager</h2><button data-control="page-processes" class:selected={session.page==='processes'} onclick={()=>send('activity.page',{page:'processes'})}>▦ Processes</button><button data-control="page-performance" class:selected={session.page==='performance'} onclick={()=>send('activity.page',{page:'performance'})}>▥ Performance</button><button onclick={()=>send('activity.panel',{panel:'preferences'})}>⚙ Settings</button><p>Local scene resources</p></aside>{/if}
 {#if capability.windows&&session.page==='performance'}
 <div class="activity-performance-content">
  <header><h2>Performance</h2><button onclick={()=>send('activity.refresh')}>Update now</button><button disabled={!process} onclick={()=>send('activity.inspect',{mode:'statistics'})}>Details — Local</button></header>
  <div class="activity-performance-body">
   <aside class="activity-resource-cards">{#each ACTIVITY_TABS as tab}<button class:selected={session.tab===tab} data-control={'resource-'+tab} onclick={()=>send('activity.tab',{tab})}><svg viewBox="0 0 70 32" aria-hidden="true"><path d="M0 8H70M0 16H70M0 24H70" class="activity-grid"/><polyline fill="none" class="activity-graph-line" points={activityGraph(session,tab).map((v,i,list)=>`${list.length>1?i*70/(list.length-1):0},${30-v*28/Math.max(1,...list)}`).join(' ')}/></svg><span><strong>{tab==='cpu'?'CPU':tab==='disk'?'Disk':tab==='network'?'Network':tab==='energy'?'Energy — Local': 'Memory'}</strong><small>{tab==='cpu'?(activityGraph(session,'cpu').at(-1)??0).toFixed(1)+'%':tab==='memory'?bytes(latest?.memoryBytes??0):tab==='energy'?(latest?.energyImpact??0).toFixed(1):bytes(activityGraph(session,tab).at(-1)??0)+'/s'}</small></span></button>{/each}</aside>
   <main bind:this={scroller} class="activity-performance-chart"><h1>{session.tab==='cpu'?'CPU':session.tab==='memory'?'Memory':session.tab==='energy'?'Energy — Local':session.tab==='disk'?'Disk':'Network'}</h1><p>{session.tab==='cpu'?'% Scene CPU utilization':session.tab==='memory'?'Actual scene application memory':session.tab==='energy'?'Authored energy impact':'Actual scene bytes per second'}</p><svg viewBox="0 0 600 260" preserveAspectRatio="none" role="img" aria-label="Performance graph from actual scene model counters"><path d="M0 52H600M0 104H600M0 156H600M0 208H600M100 0V260M200 0V260M300 0V260M400 0V260M500 0V260" class="activity-grid"/><polygon class="activity-performance-fill" points={`0,260 ${graph.map((v,i)=>`${graph.length>1?i*600/(graph.length-1):0},${258-v*256/maximum}`).join(' ')} 600,260`}/><polyline fill="none" class="activity-graph-line" points={graph.map((v,i)=>`${graph.length>1?i*600/(graph.length-1):0},${258-v*256/maximum}`).join(' ')}/></svg><div class="activity-performance-range"><span>{session.samples.length>1?((session.samples.at(-1).time-session.samples[0].time)/1000)+' seconds':'Awaiting scene time update'}</span><span>0</span></div><dl><div><dt>Processes</dt><dd>{latest?.processCount??rows.length}</dd></div><div><dt>Threads</dt><dd>{inventory?.processes?.reduce((n,p)=>n+p.counters.threads,0)??0}</dd></div><div><dt>CPU Time</dt><dd>{((latest?.cpuTimeMs??0)/1000).toFixed(2)} s</dd></div><div><dt>Memory</dt><dd>{bytes(latest?.memoryBytes??0)}</dd></div><div><dt>Read / Received</dt><dd>{bytes(session.tab==='network'?latest?.bytesReceived??0:latest?.bytesRead??0)}</dd></div><div><dt>Written / Sent</dt><dd>{bytes(session.tab==='network'?latest?.bytesSent??0:latest?.bytesWritten??0)}</dd></div></dl><p class="activity-performance-qualification">Actual local application model. Processor speed, GPU, handles, host uptime and scheduler topology are not probed or invented.</p></main>
  </div>
 </div>
 {:else}
 <div class="activity-content"><div bind:this={scroller} class="activity-table-scroll"><table aria-label="Running scene processes"><thead><tr>{#each columns as key}<th class:number={key!=='name'}><button onclick={()=>send('activity.sort',{column:key})} aria-label={'Sort by '+labels[key]}>{labels[key]}{#if session.sort===key}<span>{session.descending?'▾':'▴'}</span>{/if}</button></th>{/each}</tr></thead><tbody>{#each rows as row (row.id)}<tr class:selected={session.selectedId===row.id} onclick={()=>send('activity.select',{processId:row.id})} ondblclick={()=>send('activity.inspect',{mode:'inspector',processId:row.id})}>{#each columns as key}<td class:number={key!=='name'}>{#if key==='name'}<button data-control={'process-'+row.id} onclick={e=>{e.stopPropagation();send('activity.select',{processId:row.id});}}>{cell(row,key)}</button>{:else}{cell(row,key)}{/if}</td>{/each}</tr>{/each}</tbody></table>{#if !rows.length}<p class="activity-empty">No matching running scene applications.</p>{/if}</div>
 <footer class="activity-summary"><div><dl>{#if session.tab==='cpu'}<dt>CPU Time:</dt><dd>{((latest?.cpuTimeMs??0)/1000).toFixed(2)} s</dd><dt>Processes:</dt><dd>{latest?.processCount??rows.length}</dd>{:else if session.tab==='memory'}<dt>Physical Memory:</dt><dd>{inventory?.profile?.defaults?.machine?.memoryGB?inventory.profile.defaults.machine.memoryGB+' GB':'Not authored'}</dd><dt>Memory Used:</dt><dd>{bytes(latest?.memoryBytes??0)}</dd>{:else if session.tab==='energy'}<dt>Energy Impact:</dt><dd>{(latest?.energyImpact??0).toFixed(1)}</dd><dt>Scene applications:</dt><dd>{latest?.processCount??rows.length}</dd>{:else if session.tab==='disk'}<dt>Data read:</dt><dd>{bytes(latest?.bytesRead??0)}</dd><dt>Data written:</dt><dd>{bytes(latest?.bytesWritten??0)}</dd>{:else}<dt>Data received:</dt><dd>{bytes(latest?.bytesReceived??0)}</dd><dt>Data sent:</dt><dd>{bytes(latest?.bytesSent??0)}</dd>{/if}</dl></div>{#if activityState.preferences.showGraph}<figure><figcaption>{session.tab==='cpu'?'CPU LOAD':session.tab==='memory'?'MEMORY USED':session.tab==='energy'?'ENERGY IMPACT':session.tab==='disk'?'DISK DATA / SEC':'NETWORK DATA / SEC'}</figcaption><svg viewBox="0 0 240 60" role="img" aria-label="Graph from actual scene counter samples"><path d="M0 15H240M0 30H240M0 45H240" class="activity-grid"/><polyline points={points} fill="none" class="activity-graph-line"/></svg>{#if graph.length<2}<small>Waiting for authored scene time updates</small>{/if}</figure>{/if}<div class="activity-resource-note"><strong>{rows.length} processes</strong><span>{activityState.preferences.processes==='windowed'?'Windowed Processes':'All Scene Processes'}</span><button data-control="refresh" onclick={()=>send('activity.refresh')}>Update Now</button></div></footer></div>
 {/if}
 </div>
 {:else}
 <header class="activity-inspector-title"><span class="activity-process-icon">▣</span><div><h2>{process?activityProcessName(inventory,process):'Process exited'}</h2><p>{process?`PID ${process.pid} · ${process.id}`:session.selectedId}</p></div></header>
 {#if session.mode==='inspector'}<div class="activity-inspector-tabs">{#each ['cpu','memory','disk','network'] as tab}<button class:selected={session.tab===tab} onclick={()=>send('activity.tab',{tab})}>{tab==='cpu'?'Statistics':tab[0].toUpperCase()+tab.slice(1)}</button>{/each}</div><div bind:this={scroller} class="activity-inspector-scroll">{#if process}<dl class="activity-statistics">{#each ACTIVITY_COUNTERS.filter(k=>session.tab==='cpu'||session.tab==='memory'&&k==='memoryBytes'||session.tab==='disk'&&['bytesRead','bytesWritten'].includes(k)||session.tab==='network'&&['bytesReceived','bytesSent'].includes(k)) as key}<dt>{labels[key]??key}</dt><dd>{cell(process,key)}</dd>{/each}</dl><h3>Actual application windows</h3><ul>{#each inventory.windows.filter(w=>w.appId===process.appId) as window}<li>{window.title??window.id} <small>{window.id}</small></li>{/each}</ul>{:else}<p>The original process lifecycle has exited. Relaunching the same app does not retarget this inspector.</p>{/if}</div>{:else}<div bind:this={scroller} class="activity-diagnostic-scroll"><pre>{diagnostic}</pre></div>{/if}
 <footer class="activity-inspector-buttons"><button disabled={!process} onclick={()=>send('activity.requestQuit',{force:false})}>{capability.windows?'End task…':'Quit…'}</button><button disabled={!process} onclick={()=>send('activity.inspect',{mode:'sample'})}>Sample</button><button disabled={!process} onclick={()=>send('activity.inspect',{mode:'statistics'})}>Statistics</button><button disabled={!process} onclick={()=>send('activity.panel',{panel:'save'})}>Save…</button></footer>
 {/if}
 <div class="activity-disclosure">{capability.disclosure}</div>
 {#if error}<div role="alert" class="activity-error">{error}<button onclick={()=>error=''} aria-label="Dismiss error">×</button></div>{/if}
 {#if session.panel!=='none'}<div class="activity-sheet-shade"><section class="activity-sheet" role="dialog" aria-modal="true" aria-label={session.panel==='quit'?'Quit process':'Activity Monitor '+session.panel}>
 {#if session.panel==='quit'}<h2>{session.force?'Force quit':'Quit'} {process?activityProcessName(inventory,process):'exited process'}?</h2><p>{session.force?'Force quitting immediately ends the actual simulated application and discards its unsaved work.':'Quitting asks the actual simulated application to close. Its unsaved-document confirmation can prevent quitting.'}</p><div class="activity-sheet-buttons"><button onclick={()=>send('activity.confirmQuit',{confirm:false})}>Cancel</button><button disabled={!process} onclick={()=>send('activity.confirmQuit',{confirm:true})}>{session.force?'Force Quit':'Quit'}</button></div>
 {:else if session.panel==='preferences'}<h2>{capability.windows?'Task Manager Settings':/sonoma|golden-gate/u.test(profile.id)?'Activity Monitor Settings':'Activity Monitor Preferences'}</h2><label>Update frequency<select data-control="frequency" value={activityState.preferences.updateSeconds} onchange={e=>send('activity.preferences',{values:{...activityState.preferences,updateSeconds:Number(e.currentTarget.value)}})}><option value={1}>Very often (1 sec)</option><option value={2}>Often (2 sec)</option><option value={5}>Normally (5 sec)</option></select></label><label>Processes<select value={activityState.preferences.processes} onchange={e=>send('activity.preferences',{values:{...activityState.preferences,processes:e.currentTarget.value}})}><option value="all">All Scene Processes</option><option value="windowed">Windowed Processes</option></select></label><label class="activity-checkbox"><input type="checkbox" checked={activityState.preferences.showGraph} onchange={e=>send('activity.preferences',{values:{...activityState.preferences,showGraph:e.currentTarget.checked}})}/>Show scene-derived graph</label><p>Updates use the authored scene clock, not real-world elapsed time.</p><button onclick={()=>send('activity.panel',{panel:'none'})}>Done</button>
 {:else if session.panel==='save'}<h2>Save Local Process Sample</h2><label>Save As<input data-control="save-name" bind:value={saveName} maxlength="256"/></label><p>Plain text diagnostics from the original process counters and actual windows.</p><div class="activity-sheet-buttons"><button onclick={()=>send('activity.panel',{panel:'none'})}>Cancel</button><button disabled={!process} onclick={()=>send('activity.saveSample',{name:saveName})}>Save to Documents</button></div>
 {:else}<h2>{capability.label} Help</h2><p>The resource table contains only applications actually running in this scene. Search by app name or PID and click a column to sort. Inspectors retain the original lifecycle; a restarted application is a new process.</p><p>CPU is the authored process CPU time divided by authored elapsed scene time. Graphs record the actual counters when scene time changes or Update Now is selected. Disk and network graphs show differences between actual samples, not live host traffic.</p><p>{capability.disclosure}</p><button onclick={()=>send('activity.panel',{panel:'none'})}>Done</button>{/if}
 </section></div>{/if}
</section>{/if}
